from base_sensor import BaseVirtualSensor

class BME280_Simulator(BaseVirtualSensor):
    REG_WIDTH = 8

    def __init__(self):
        super().__init__()
        self.regs = {
            0xD0: 0x60,  # id
            0xE0: 0x00,  # reset
            0xF2: 0x00,  # ctrl_hum
            0xF3: 0x00,  # status
            0xF4: 0x00,  # ctrl_meas
            0xF5: 0x00,  # config
            0xF7: 0x80,  # press_msb
            0xF8: 0x00,  # press_lsb
            0xF9: 0x00,  # press_xlsb
            0xFA: 0x80,  # temp_msb
            0xFB: 0x00,  # temp_lsb
            0xFC: 0x00,  # temp_xlsb
            0xFD: 0x00,  # hum_msb
            0xFE: 0x00,  # hum_lsb
        }

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        if addr not in self.regs:
            raise ValueError(f"Invalid register address: {addr:#04x}")

        if nbytes == 2:
            return self.regs[addr]
        elif nbytes == 1:
            return (self.regs[addr] >> 8) & 0xFF
        else:
            raise ValueError("Invalid nbytes value. Must be 1 or 2.")

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if addr not in self.regs:
            raise ValueError(f"Invalid register address: {addr:#04x}")

        if addr == 0xE0:  # reset
            if data == 0xB6:
                self._reset()
            return

        if nbytes == 2:
            self.regs[addr] = data & 0xFFFF
        elif nbytes == 1:
            self.regs[addr] = (self.regs[addr] & 0x00FF) | ((data & 0xFF) << 8)
        else:
            raise ValueError("Invalid nbytes value. Must be 1 or 2.")

    def _reset(self):
        self.regs = {
            0xD0: 0x60,  # id
            0xE0: 0x00,  # reset
            0xF2: 0x00,  # ctrl_hum
            0xF3: 0x00,  # status
            0xF4: 0x00,  # ctrl_meas
            0xF5: 0x00,  # config
            0xF7: 0x80,  # press_msb
            0xF8: 0x00,  # press_lsb
            0xF9: 0x00,  # press_xlsb
            0xFA: 0x80,  # temp_msb
            0xFB: 0x00,  # temp_lsb
            0xFC: 0x00,  # temp_xlsb
            0xFD: 0x00,  # hum_msb
            0xFE: 0x00,  # hum_lsb
        }
